```cpp
class IntSLinkedList {
public:
    class Node; // Forward declaration

private:
    Node* head;
    Node* tail;
    int count;

public:
    IntSLinkedList() : head(NULL), tail(NULL), count(0) {};
    void add(int element) {
        Node* newNode = new Node(element);
        if (head == NULL) {head = newNode; tail = newNode; ++count; return;}
        this->tail->next = newNode;
        tail = newNode;
        ++count;
        return;
    }
    void add(int index, int element) {
        int size = this->size();
        if (index > size || index < 0) return;
        if (index == size || head == NULL) {this->add(element); return;}
        if (index == 0)
        {
            ++count;
            Node* newNode = new Node(element);
            newNode->next = head;
            head = newNode;
            return;
        }
    }

